/**
 * Dataset loading.
 *
 * Two tiers, kept separate on purpose:
 *
 *  - **gold** — hand-written questions with hand-checked file labels. Small,
 *    slow to produce, and the number worth quoting.
 *  - **silver** — questions generated by Claude from a sampled chunk, with the
 *    chunk's own file as the label. Cheap and plentiful, but biased: a question
 *    written *from* a passage shares vocabulary with it, which flatters lexical
 *    retrieval. Reported separately, never pooled with gold.
 */
import fs from 'fs'
import path from 'path'

export interface EvalQuery {
  id: string
  repo: string
  /**
   * `symbol_exact` is a bare identifier with no surrounding prose — the way
   * developers actually search when they already know the name. It is kept
   * apart from `symbol` (which asks the same thing in a full sentence) because
   * the two have opposite retrieval characteristics.
   */
  type: 'symbol' | 'symbol_exact' | 'concept' | 'howto' | 'architecture' | 'debug'
  question: string
  relevantFiles: string[]
  tier: 'gold' | 'silver'
  /** Silver only: the kind of file the label points at, for breakdowns. */
  sourceKind?: string
}

const DATASET_DIR = path.join(process.cwd(), 'eval', 'datasets')

function readJsonl(file: string, tier: 'gold' | 'silver'): EvalQuery[] {
  if (!fs.existsSync(file)) return []
  return fs
    .readFileSync(file, 'utf-8')
    .split('\n')
    .filter((line) => line.trim().length > 0)
    .map((line) => ({ ...JSON.parse(line), tier }))
}

export function loadDataset(tier?: 'gold' | 'silver'): EvalQuery[] {
  const files = fs.existsSync(DATASET_DIR) ? fs.readdirSync(DATASET_DIR) : []
  const queries: EvalQuery[] = []

  for (const file of files) {
    if (file.endsWith('.gold.jsonl') && tier !== 'silver') {
      queries.push(...readJsonl(path.join(DATASET_DIR, file), 'gold'))
    }
    if (file.endsWith('.silver.jsonl') && tier !== 'gold') {
      queries.push(...readJsonl(path.join(DATASET_DIR, file), 'silver'))
    }
  }

  return queries
}

export function groupByRepo(queries: EvalQuery[]): Map<string, EvalQuery[]> {
  const grouped = new Map<string, EvalQuery[]>()
  for (const q of queries) {
    const list = grouped.get(q.repo) ?? []
    list.push(q)
    grouped.set(q.repo, list)
  }
  return grouped
}
